class Solution:
    def treeQueries(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        adj = [[] for _ in range(n + 1)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        tin = [0]*(n+1); tout = [0]*(n+1); wt = [0]*(n+1); par = [0]*(n+1)
        timer = 0
        st = [(1, 0, False)]
        while st:
            node, p, done = st.pop()
            if done:
                tout[node] = timer - 1
                continue
            tin[node] = timer; timer += 1; par[node] = p
            st.append((node, p, True))
            for v, w in adj[node]:
                if v != p:
                    wt[v] = w
                    st.append((v, node, False))
        bit = [0]*(n + 2)
        def upd(i, d):
            i += 1
            while i <= n + 1:
                bit[i] += d; i += i & -i
        def qr(i):
            i += 1; s = 0
            while i > 0:
                s += bit[i]; i -= i & -i
            return s
        res = []
        for q in queries:
            if q[0] == 1:
                _, u, v, w = q
                c = u if par[u] == v else v
                d = w - wt[c]; wt[c] = w
                upd(tin[c], d); upd(tout[c] + 1, -d)
            else:
                res.append(qr(tin[q[1]]))
        return res

