class Solution {
public:
    vector<long long> treeQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<pair<int,int>>> adj(n+1);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        vector<int> tin(n+1), tout(n+1), wt(n+1), par(n+1);
        int timer = 0;
        vector<array<int,3>> st = {{1,0,0}};
        while (!st.empty()) {
            auto [node, p, done] = st.back(); st.pop_back();
            if (done) { tout[node] = timer - 1; continue; }
            tin[node] = timer++; par[node] = p;
            st.push_back({node, p, 1});
            for (auto& [v, w] : adj[node]) if (v != p) { wt[v] = w; st.push_back({v, node, 0}); }
        }
        vector<long long> bit(n + 2, 0);
        auto upd = [&](int i, long long d) { for (++i; i <= n + 1; i += i & -i) bit[i] += d; };
        auto qr = [&](int i) { long long s = 0; for (++i; i > 0; i -= i & -i) s += bit[i]; return s; };
        vector<long long> res;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int u = q[1], v = q[2], w = q[3];
                int c = (par[u] == v) ? u : v;
                long long d = w - wt[c]; wt[c] = w;
                upd(tin[c], d); upd(tout[c] + 1, -d);
            } else res.push_back(qr(tin[q[1]]));
        }
        return res;
    }
};

