class Solution {
    public long[] treeQueries(int n, int[][] edges, int[][] queries) {
        List<int[][]> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new int[0][]);
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(new int[]{e[1], e[2]}); g.get(e[1]).add(new int[]{e[0], e[2]}); }
        int[] tin = new int[n+1], tout = new int[n+1], wt = new int[n+1], par = new int[n+1];
        int timer = 0;
        Deque<int[]> st = new ArrayDeque<>(); st.push(new int[]{1, 0, 0});
        while (!st.isEmpty()) {
            int[] top = st.pop();
            int node = top[0], p = top[1];
            if (top[2] == 1) { tout[node] = timer - 1; continue; }
            tin[node] = timer++; par[node] = p;
            st.push(new int[]{node, p, 1});
            for (int[] vw : g.get(node)) if (vw[0] != p) { wt[vw[0]] = vw[1]; st.push(new int[]{vw[0], node, 0}); }
        }
        long[] bit = new long[n + 2];
        java.util.List<Long> resList = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int c = (par[q[1]] == q[2]) ? q[1] : q[2];
                long d = q[3] - wt[c]; wt[c] = q[3];
                for (int i = tin[c] + 1; i <= n + 1; i += i & -i) bit[i] += d;
                for (int i = tout[c] + 2; i <= n + 1; i += i & -i) bit[i] -= d;
            } else {
                long s = 0;
                for (int i = tin[q[1]] + 1; i > 0; i -= i & -i) s += bit[i];
                resList.add(s);
            }
        }
        long[] res = new long[resList.size()];
        for (int i = 0; i < res.length; i++) res[i] = resList.get(i);
        return res;
    }
}

