var treeQueries = function(n, edges, queries) {
    const adj = Array.from({length: n + 1}, () => []);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }
    const tin = new Array(n+1).fill(0), tout = new Array(n+1).fill(0), wt = new Array(n+1).fill(0), par = new Array(n+1).fill(0);
    let timer = 0;
    const st = [[1, 0, false]];
    while (st.length) {
        const [node, p, done] = st.pop();
        if (done) { tout[node] = timer - 1; continue; }
        tin[node] = timer++; par[node] = p;
        st.push([node, p, true]);
        for (const [v, w] of adj[node]) if (v !== p) { wt[v] = w; st.push([v, node, false]); }
    }
    const bit = new Array(n + 2).fill(0);
    const upd = (i, d) => { for (i++; i <= n + 1; i += i & -i) bit[i] += d; };
    const qr = i => { let s = 0; for (i++; i > 0; i -= i & -i) s += bit[i]; return s; };
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const c = par[q[1]] === q[2] ? q[1] : q[2];
            const d = q[3] - wt[c]; wt[c] = q[3];
            upd(tin[c], d); upd(tout[c] + 1, -d);
        } else res.push(qr(tin[q[1]]));
    }
    return res;
};
